import type { Router } from 'vue-router'

export function setupAuthGuard(router: Router) {
  router.beforeEach((to, _from, next) => {
    const token = localStorage.getItem('token')
    if (to.meta.requiresAuth && !token) {
      next('/login')
    } else {
      next()
    }
  })
}
